'use strict';
const C=require('../index'),questions=require('./security-questions');
const SID='api-security-auth',COMMIT='121e76561a58a28790fd7fa927236eec8d63ea59',lessons=[];
const section=(heading,a,b,extra={})=>({heading,paragraphs:[a,b],...extra});
function add(id,comp,title,introduction,sections,code,expect,problem,steps,explanation,mistakes,takeaways,references){const o=C.competency(SID+'.'+comp);lessons.push({id,module:o.module,version:1,title,minutes:45,objectives:[{id:SID+'.'+comp,text:o.competency.text}],prerequisites:lessons.length?[lessons.at(-1).id]:[],prerequisite_note:lessons.length?'Use the preceding identity, trust-boundary and permission vocabulary. Revisit any earlier example when its assumptions are needed.':'REST API Design is the canonical prerequisite. HTTP Foundations explains transport/browser mechanisms and REST explains resource contracts. Here those concepts support defensive security decisions; all examples use synthetic values and all assessment is MCQ-based.',introduction,sections,worked:{lang:'python',code,expect,problem,steps,explanation},mistakes,takeaways,references,reuse:[],quiz:questions[id].slice(0,3).map(q=>q.id)});}
add('sec-passwords','m1.c1','Protect stored passwords with adaptive salted hashing',
 'A customer platform must verify a password without retaining a recoverable copy. If its credential database is disclosed, protection should make each offline guess expensive while allowing legitimate logins at a measured cost. This is one boundary in a larger identity system, not permission to every customer record.',[
 section('Separate secrecy goals and credential types','Authentication establishes a caller’s identity; authorization decides what that caller may do. Confidentiality protects private information, integrity protects authorized meaning/state and availability protects usable service. Password storage mainly limits damage from disclosure of verification data; TLS, account lifecycle, permissions and abuse controls remain separate layers.','Passwords are typically low-entropy human choices and need an adaptive password-hashing/KDF design rather than fast SHA-256 alone or reversible encryption. A salt is a per-record random value that makes equal passwords produce different stored results. It need not be secret. A pepper, where used, is a separately protected secret and does not replace salting or work factors.'),
 section('Use maintained implementations and explicit cost policy','The pinned OWASP guidance prefers Argon2id and documents scrypt when it is unavailable. PBKDF2-HMAC-SHA256 at 600,000 or more iterations is a documented alternative for relevant FIPS-oriented requirements. FIPS assurance depends on an appropriately validated implementation/configuration, not merely selecting an algorithm name. Benchmark costs and review them over time rather than lowering them to make tests quick.','A production password record needs algorithm/version, cost parameters, salt and derived result under a maintained library’s format. Compare through its verification API and upgrade records according to policy. Never log raw passwords or silently truncate input. Generic login errors, request limits, recovery rules and MFA protect different attack paths; salted hashing is not a complete login service.'),
 section('Security note: interpret this bounded example correctly','The fixture uses PBKDF2’s documented work factor with fixed clearly synthetic salts so outputs are repeatable. Real salts must be generated with an appropriate cryptographic random source; this fixture is not a salt-generation recommendation. The output exposes only equality decisions, not credential material.','The same password/salt reproduces a verifier; another input does not, and another salt changes the derived result. These checks do not prove password strength, FIPS validation, production latency or a constant-time complete account lookup. hmac.compare_digest handles this comparison, while the surrounding login flow still requires careful error/timing design.',{diagram:'Untrusted request -> verified identity -> scoped permission -> validated operation\n                       |                     |                   |\n                    expiry/revoke        owner + tenant      minimal response',table:{headers:['Control','Boundary it does not replace'],rows:[['Adaptive password hashing','Object permission checks'],['Unique salt','A secret pepper or account policy'],['Verified TLS','Secure credential storage'],['Generic login error','Rate limits and lifecycle controls']]}})],
 'import hashlib, hmac\ndef derive(password, salt):\n    return hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 600000)\nsalt = b"fixture-salt-001"\nstored = derive("SYNTHETIC-PASSWORD", salt)\nprint(hmac.compare_digest(stored, derive("SYNTHETIC-PASSWORD", salt)))\nprint(hmac.compare_digest(stored, derive("SYNTHETIC-WRONG", salt)))\nprint(stored != derive("SYNTHETIC-PASSWORD", b"fixture-salt-002"))','True\nFalse\nTrue',
 'Verify synthetic password inputs and demonstrate the effect of a distinct fixture salt without printing stored credential data.',['Derive the fixture record with the declared adaptive cost.','Compare a matching and a different synthetic input.','Compare a different salt while keeping the password constant.'],'The decisions match the declared inputs. The fixture salts are test data; production salt generation, record formatting, throttling and algorithm selection still need a reviewed implementation.',
 ['Fast hashing alone makes human-password guesses too cheap.','A salt is not a replacement for cost, a separate pepper policy or authorization.','A working algorithm call does not establish full login timing or compliance assurance.'],['Treat password verification data as sensitive even when not plaintext.','Use maintained adaptive hashing with reviewed parameters.','Keep credential storage, authentication and authorization boundaries distinct.'],['passwords','authentication']);
add('sec-sessions','m1.c2','Design session and refresh-credential lifecycle',
 'A subscription dashboard keeps users signed in across requests and replicas. The session’s authority must begin, change and end deliberately. Clearing a screen is not the same as revoking the server-recognized credential.',[
 section('A session is authority with an expiry policy','A server session identifier refers to trusted server state. Generate it with sufficient unpredictable entropy, protect it in transit/storage and rotate it when the authentication context changes according to policy. Shared state or a deliberately designed credential strategy is needed when requests can reach different replicas.','Define absolute and inactivity expiry, logout, password-change/reset effects and privilege-change handling. A new role should not be trusted merely because a long-lived cookie still contains an old claim. Server-side sessions can support revocation centrally; the store needs access controls, availability and lifecycle cleanup.'),
 section('Choose browser storage and token tradeoffs explicitly','A token is a credential representation; a cookie is a browser storage/sending mechanism, so a token can be in a cookie. Secure restricts cookie transport under browser rules; HttpOnly limits JavaScript access; SameSite affects cross-site sending. None supplies every authorization, XSS or CSRF defense. A host-only scope and appropriate Path/lifetime reduce unnecessary exposure.','Refresh credentials can extend access and need stronger lifecycle handling, rotation/reuse detection where applicable, secure transport/storage and a defined revocation policy. Self-contained access tokens can remain valid until expiry unless a server-side revocation/version strategy is consulted. Do not promise instant logout revocation from local client deletion alone.'),
 section('Resolve identity from trusted state on each request','The server uses the presented credential to recover/verify identity, then authorizes the target operation. Caller-supplied user_id in a body must not replace that identity. Never write raw session/refresh credentials into correlation ids, copied URLs or routine logs.','The example models a server-side record with explicit expiry and logout revocation. It does not create a secure random session, implement distributed inactivity tracking or render a browser cookie. Its purpose is to make lifecycle decisions observable and test the exact expiry boundary.',{snippet:{lang:'http',code:'Set-Cookie: session=SYNTHETIC-ONLY; Path=/; Secure; HttpOnly; SameSite=Lax'}})],
 'sessions = {"fixture-session": {"user_id": 7, "expires": 200, "revoked": False}}\ndef resolve(token, now):\n    row = sessions.get(token)\n    if not row or row["revoked"] or now >= row["expires"]:\n        return None\n    return row["user_id"]\nprint(resolve("fixture-session", 199))\nprint(resolve("fixture-session", 200))\nsessions["fixture-session"]["revoked"] = True\nprint(resolve("fixture-session", 150))','7\nNone\nNone',
 'Reject a synthetic session exactly at expiry and after recorded logout revocation.',['Resolve only known fixture session state.','Apply the server-side expiry rule with a fixed clock.','Set the revocation state and verify that earlier clock time does not bypass it.'],'The session resolves before expiry, fails at expiry and fails after revocation. The dictionary is explanatory local state, not a durable distributed session implementation.',
 ['Deleting a browser value does not necessarily revoke every server-recognized credential.','HttpOnly restricts script access, not every authenticated browser request.','A body user_id is not a trusted replacement for the verified actor.'],['Specify session and refresh lifecycle end to end.','Choose cookie and token transport with their separate defenses.','Recover identity from trusted state before object authorization.'],['sessions','authentication','rest']);
add('sec-token-policy','m1.c2','Validate token trust before interpreting claims',
 'An API receives a structured access token whose payload can be decoded. Readable claims are not proof of authenticity, and a valid signature for one service is not automatically authority for another. Token acceptance is a configured trust decision.',[
 section('Separate decoding, cryptographic trust and claim policy','A signed token need not be encrypted; a holder may be able to read its claims. A maintained verification library should enforce the configured signature algorithm, trusted key selection and required claims. Do not let untrusted header fields choose arbitrary verification behavior or a caller-supplied key location.','After cryptographic verification, require the intended issuer, audience and time rules, plus subject/credential type and other application requirements. Expiry is not optional simply because a signature is valid. Define clock skew/leeway deliberately, not by making the acceptance window unlimited. Algorithm/key rotation and token-type boundaries need their own reviewed policy.'),
 section('Bind audience and lifecycle to the resource server','A token for a reporting API must not be accepted by a payment API solely because the same identity provider signed it. Permission scopes and roles need validation and context; a token with the correct audience can still lack permission for one order. Long lifetimes and stale claims increase revocation/privilege-change tradeoffs.','A JWT does not automatically eliminate server state or session lifecycle requirements. Revocation lists, session versions or short-lived access plus carefully controlled refresh can be appropriate under different constraints. Logout must be defined in terms of what the resource server will actually reject, not only what the browser deletes.'),
 section('This example begins after signature verification','The function below checks a narrow post-verification claim policy on synthetic dictionaries. It does **not** parse, sign or validate a real JWT. No boolean claim such as verified=true supplied by a client could substitute for the missing cryptographic step.','The fixture requires integer expiry under its explicitly narrow contract and rejects it at equality. Production NumericDate handling may permit another documented numeric representation and bounded leeway. Use a maintained token library and tests for the actual format, issuer, audience, key rotation and lifecycle policy.')],
 'def claim_policy(verified_claims, now):\n    return (verified_claims.get("iss") == "fixture-issuer"\n            and verified_claims.get("aud") == "reporting-api"\n            and type(verified_claims.get("exp")) is int\n            and now < verified_claims["exp"])\nclaims = {"iss": "fixture-issuer", "aud": "reporting-api", "exp": 200}\nprint(claim_policy(claims, 199))\nprint(claim_policy(claims, 200))\nprint(claim_policy({**claims, "aud": "payments-api"}, 100))\nprint(claim_policy({**claims, "exp": True}, 100))','True\nFalse\nFalse\nFalse',
 'Check expiry and audience for synthetic claims assumed to have already passed a real library’s cryptographic verification.',['State the external verification precondition explicitly.','Compare the expected issuer/audience and exact fixture expiry policy.','Test equality, wrong audience and a Boolean value masquerading as an integer.'],'Only the pre-expiry intended-audience fixture passes. This result is not authentication of a real token and does not establish object permissions.',
 ['Decoding is not signature verification.','A valid signature is not sufficient audience, expiry or authorization policy.','A toy claim predicate must not be used as a complete JWT validator.'],['Configure token trust instead of accepting caller-selected trust.','Validate required claims and credential purpose.','Document lifecycle, clock and revocation behavior.'],['rest','sessions','authentication']);
add('sec-recovery-mfa','m1.c3','Make password recovery and MFA part of the security boundary',
 'A strong password flow can be undermined by a weaker recovery path. A customer-support portal needs identity recovery without exposing whether a private account exists or treating possession of an email address string as proof of ownership.',[
 section('Treat reset tokens as temporary credentials','Use a sufficiently unpredictable cryptographically generated reset value, bind it to the intended account/purpose, expire it and consume it once under a coordinated state change. Store an appropriate verifier for a high-entropy token rather than logging/recovering it unnecessarily. Unlike human passwords, high-entropy random reset tokens have a different guessing model; a fast digest can be suitable for their stored verifier.','Return a consistent safe reset-request response for present/absent accounts under the product’s disclosure policy, and review timing, abuse limits and delivery behavior as well as wording. Build links from trusted configuration, not arbitrary caller host data. Successful recovery should trigger the required session/refresh revocation and notifications without exposing the new password.'),
 section('Require independent factors and protect enrollment/removal','MFA combines factors such as something known and a securely possessed authenticator. Two knowledge questions are not necessarily two independent factors. Some methods are more phishing-resistant than others, and recovery codes/device replacement deserve the same attention as normal login.','Changing a recovery address, enrolling/removing MFA or performing a high-impact operation can require recent authentication/step-up under policy. Do not let an ordinary support request silently bypass these controls. Recovery events need privacy-aware audit records and a reviewed human support process where one is required.'),
 section('Coordinate one-time use and test failure paths','The fixture uses a clearly synthetic token and stored digest with fixed times. Wrong, expired and reused inputs are rejected. A real concurrent implementation needs atomic consumption so two workers cannot both accept before marking used; the dictionary cannot prove that guarantee.','The demonstration does not generate production entropy, deliver mail, recover a real account or implement an MFA authenticator. Review both successful recovery and failure/rate-limit paths, and never describe a generic response alone as complete enumeration protection.')],
 'import hashlib, hmac\nrecord = {"digest": hashlib.sha256(b"SYNTHETIC-RESET-ONLY").digest(), "expires": 200, "used": False}\ndef consume(value, now):\n    if record["used"] or now >= record["expires"]:\n        return False\n    if not hmac.compare_digest(hashlib.sha256(value.encode()).digest(), record["digest"]):\n        return False\n    record["used"] = True\n    return True\nprint(consume("SYNTHETIC-WRONG", 100))\nprint(consume("SYNTHETIC-RESET-ONLY", 200))\nprint(consume("SYNTHETIC-RESET-ONLY", 150))\nprint(consume("SYNTHETIC-RESET-ONLY", 150))','False\nFalse\nTrue\nFalse',
 'Accept one valid unexpired synthetic reset use while rejecting wrong, expired and repeated uses.',['Check expiry/use state before accepting a value.','Compare the stored verifier without logging token material.','Mark one successful fixture use and observe reuse rejection.'],'The local sequence illustrates a lifecycle policy. It is not proof of atomic multi-worker consumption, generated token entropy or a working recovery/MFA service.',
 ['Recovery is an authentication boundary, not an exception to it.','A token’s unpredictable generation, scope, expiry and one-time consumption are separate requirements.','A fixed fixture string is not a production reset-token generator.'],['Protect recovery at least as deliberately as normal login.','Use independent factors and controlled lifecycle changes.','Test wrong, expired, used and concurrent-consumption policies.'],['recovery','mfa','authentication']);
add('sec-object-access','m2.c1','Enforce record permissions for every requested object',
 'A student may read their own assessment history but not another learner’s private results. Changing a numeric id in a request must never change who the server considers authenticated. The same rule must hold on detail, list, export and historical-attempt routes.',[
 section('Authorize an action on an actual target','Begin with the verified server-side actor, the requested action and the loaded target object or constrained query. Check ownership/tenant and any explicitly delegated permission. A valid session only establishes identity; an opaque id, a hidden button or a matching route prefix is not authorization.','Prefer a shared policy/service boundary with tests rather than copying incomplete checks across handlers. Fail closed when identity, object ownership or required permission state is absent or ambiguous. Recheck relevant state at the real operation boundary; the presence of a link in an earlier representation is not permanent authority.'),
 section('Check collections and derived resources too','A list endpoint must restrict the selected population, not fetch every learner and rely on the browser to hide unauthorized rows. Export, search, counts, attachments and attempt-review routes can leak data even when the main detail route is correct. Field-level projection follows object permission rather than replacing it.','A consistent undisclosed/not-found response policy can reduce existence disclosure where appropriate, but denial wording does not replace the access decision. Avoid logging entire denied objects; record a nonsecret correlation and safe category instead. Authorization is a server responsibility even when every public API client is owned by the same organization.'),
 section('Use negative cases to make the boundary concrete','The fixture receives actors from trusted test setup and compares them with synthetic history owners. It rejects another learner, an absent actor and a client body that claims a different owner. The body is ordinary data, not an identity source.','This is a small ownership policy, not a complete delegated-access model. If staff or guardians need access, define scoped permissions and audit rules explicitly rather than adding a universal admin bypass. A passing self-access case alone cannot demonstrate isolation.',{diagram:'Verified actor + action + target ownership/context → server policy decision\nClient-supplied owner/role fields → ordinary untrusted input, not identity'})],
 'history = {"id": "history-9", "owner_id": 7}\ndef may_read(actor, target):\n    return actor is not None and actor["id"] == target["owner_id"]\nprint(may_read({"id": 7}, history))\nprint(may_read({"id": 8}, history))\nprint(may_read(None, history))\nbody = {"owner_id": 7}\nprint(may_read({"id": 8}, history))','True\nFalse\nFalse\nFalse',
 'Keep one synthetic learner’s history private despite another caller supplying an owner field.',['Use the verified fixture actor instead of the body’s identity claim.','Compare the target owner for each call.','Test correct owner, different owner and absent identity.'],'Only the actual owner passes. The unused body demonstrates that submitted identity data does not become authority; production policy may include additional explicitly scoped roles.',
 ['Authenticated does not mean authorized for every object.','Obscure ids and hidden UI controls are not access boundaries.','Protect list/export/count/history routes as well as detail routes.'],['Apply object permission on every operation.','Recover the actor from trusted authentication.','Include cross-user and missing-context cases in tests.'],['authorization','rest']);
add('sec-roles','m2.c2','Model RBAC without losing resource scope',
 'A support coordinator may read cases while a finance employee may issue refunds. A role helps organize permissions, but the role’s name is not the complete access decision. The permission must apply to the requested action and relevant organization/resource context.',[
 section('Map roles to explicit capabilities','Role-based access control assigns permissions to roles and trusted memberships to actors. Use capabilities such as case:read or invoice:read rather than letting each handler guess what “staff” means. Default deny when a capability is unknown or not granted. Keep the policy vocabulary small enough to review and test.','Role membership must come from a trusted identity/authorization source, not a request field or unverified token claim. A front-end role menu is presentation. Role changes, temporary delegation and high-impact privileges need lifecycle/expiry/audit policy; stale cached claims can retain more authority than intended.'),
 section('Separate role permission from object/tenant predicates','A reporting role may read invoices only in one tenant. A role check can grant the action while ownership rules limit the target population. Cross-organization administrators or emergency access require an explicit separately reviewed policy, not an accidental bypass applied whenever role == admin.','RBAC is useful but not every contextual rule fits a static role explosion. Ownership, assigned case, consent or time-bound delegation may require additional attributes/relationships. Do not create hundreds of ad hoc role strings to hide an undocumented object policy. Define the decision inputs and enforce them consistently.'),
 section('Evaluate permissions from trusted context','The fixture maps roles to action sets and requires tenant equality as a separate predicate. It permits a scoped read, rejects a write not in the role and rejects the same permitted action in another tenant. Unknown roles receive no permissions.','It does not implement a production permission database, token validation or revocation cache. It shows why a role grant is a component of a policy rather than a replacement for target scope and lifecycle controls.',{table:{headers:['Decision input','Required evidence'],rows:[['Actor role','Trusted membership, not form input'],['Action','Explicit granted capability'],['Resource scope','Ownership/tenant/relationship policy'],['Change/revocation','Actual server-recognized lifecycle']]}})],
 'permissions = {"reporter": {"invoice:read"}, "finance": {"invoice:read", "refund:create"}}\ndef allowed(actor, action, tenant):\n    return actor["tenant"] == tenant and action in permissions.get(actor["role"], set())\nactor = {"tenant": 3, "role": "reporter"}\nprint(allowed(actor, "invoice:read", 3))\nprint(allowed(actor, "refund:create", 3))\nprint(allowed(actor, "invoice:read", 4))\nprint(allowed({**actor, "role": "unknown"}, "invoice:read", 3))','True\nFalse\nFalse\nFalse',
 'Apply one trusted role grant together with a tenant constraint.',['Look up only explicitly granted capabilities.','Check the action and target tenant together.','Test disallowed action, wrong tenant and unknown role.'],'The reporter can read the scoped invoice but gains neither refund authority nor cross-tenant access. Real role assignment/revocation remains outside this fixture.',
 ['A client-provided role string is not a grant.','A broad staff label can conceal unrelated sensitive actions.','Role permission alone does not settle resource/tenant scope.'],['Use explicit least-privilege capabilities.','Combine role grants with context checks.','Test unknown, changed and cross-scope memberships.'],['authorization']);
add('sec-tenant-responses','m2.c1','Isolate tenant data and minimize response fields',
 'Several organizations use one subscription API. An organization identifier in the URL selects a target; it must not let a caller choose a new identity or browse every valid database row. Data isolation and response minimization must survive every code path.',[
 section('Bind tenant context to verified membership','Determine the actor’s allowed organization from trusted membership and select only matching objects. A tenant-aware foreign key can protect stored links, as Database Design explains, but cannot authorize a SELECT. Filtering must include the right tenant/object predicates before returning data, including paginated lists, totals and exports.','Cache keys and background work also need the correct isolation context. A cache hit must not bypass permissions or mix representations from different tenants. Carry scoped operation identity into asynchronous jobs; a worker that trusts arbitrary payload tenant_id can recreate the same boundary defect outside the request handler.'),
 section('Project permitted data instead of serializing internal objects','A correct object permission does not authorize every attribute. A public invoice summary may need id and status but not internal risk notes, provider credentials or another user’s contact record. Use a reviewed output schema/allowlist, with separate create/update input schemas to avoid overposting.','Minimization also reduces accidental logging and support disclosure, but it is not redaction proof for all future data shapes. Test nested objects, new fields and negative access cases. A generic remove-the-password step can miss refresh tokens, keys and sensitive domain attributes.'),
 section('Demonstrate both row scope and field scope','The example selects synthetic tenant 3 records for a trusted tenant 3 actor and returns an allowed subset of fields. It does not expose internal notes even for the selected row and does not return tenant 4’s record at all.','A real implementation should enforce authorized queries and protect storage/cache boundaries rather than first loading a global dataset in application memory. This small list illustrates the policy result, not an optimized database query or a universal serialization framework.')],
 'rows = [{"id": "inv-1", "tenant": 3, "status": "paid", "internal_note": "SYNTHETIC-PRIVATE"}, {"id": "inv-2", "tenant": 4, "status": "due", "internal_note": "SYNTHETIC-PRIVATE"}]\nactor = {"tenant": 3}\npublic = [{"id": r["id"], "status": r["status"]} for r in rows if r["tenant"] == actor["tenant"]]\nprint(public)\nprint(all("internal_note" not in r for r in public))','[{\'id\': \'inv-1\', \'status\': \'paid\'}]\nTrue',
 'Return only the current tenant’s invoice summaries and omit internal-only fields.',['Derive the fixture tenant from trusted actor state.','Restrict the record population.','Project allowed public summary properties and inspect the output.'],'One safe summary remains and contains no internal note. This does not verify a real cache, query planner or every nested response model.',
 ['A tenant id supplied by the caller is a target selector, not proof of membership.','A valid database reference does not grant read access.','Correct row ownership does not authorize unrestricted field serialization.'],['Apply tenant scope across requests, caches and jobs.','Minimize fields through reviewed projections.','Test cross-tenant and nested/new-field cases.'],['authorization','rest']);
add('sec-commerce-review','m2.c1','Review a payment-related operation across trust boundaries',
 'A customer requests a refund for an order. The API must verify the caller, the order ownership, the permitted business transition and the writable fields before scheduling financial work. A successful individual check is not enough if another path trusts the client’s claim instead.',[
 section('Write an authorization and invariant matrix','List actors, target resources and allowed actions, including negative cases. Customer read-own-order is different from staff refund-create. Decide whether a customer may request a refund or directly execute one, and whether a recent authentication/step-up policy is required. The fixture chooses only a customer refund-request capability.','Identify authoritative values: authenticated actor from trusted state, order owner/paid amount from server records, current status from the business store. Do not accept a client owner_id, charged amount or internal approval flag as the source of truth. State-conflict checks must hold at the actual operation boundary, not only when a page loaded.'),
 section('Minimize the instruction and coordinate its effects','Validate a narrowly scoped request, authorize the target, then create a tracked operation under an idempotency/reconciliation contract. REST API Design covers uncertain remote effects; local security checks do not make an external charge/refund atomic with the order database. Never invent a completed refund because a job was queued.','Return a safe request id/status rather than provider credentials or private history. Audit the verified actor, action and safe target reference under access/retention policy. Unknown state, missing authority or malformed input should not silently escalate to success; error disclosure rules remain consistent.'),
 section('Use cross-owner cases without live account testing','The fixture rejects a different actor even when the submitted body claims the order’s owner. It ignores no ownership boundary merely because payment status is paid. Successful self access returns only an accepted refund-request decision, not a completed financial reversal.','This is a local design predicate, not a refund server or live security test. Production code still needs atomic operation coordination, provider authentication, step-up policy where required and safe repeated-request behavior. No public account or payment system is contacted.')],
 'order = {"id": "ord-demo", "owner": 7, "state": "paid"}\ndef request_refund(actor, body):\n    if actor is None or actor["id"] != order["owner"]:\n        return "denied"\n    if set(body) != {"reason"} or not isinstance(body["reason"], str) or not 1 <= len(body["reason"]) <= 200:\n        return "invalid_request"\n    if order["state"] != "paid":\n        return "state_conflict"\n    return "request_accepted"\nprint(request_refund({"id": 8}, {"owner": 7, "reason": "duplicate"}))\nprint(request_refund({"id": 7}, {"reason": "duplicate"}))\nprint(request_refund({"id": 7}, {"reason": "duplicate", "approved": True}))','denied\nrequest_accepted\ninvalid_request',
 'Accept a narrow own-order request while denying another actor and a managed-property submission.',['Use the trusted actor and stored owner for authorization.','Allow only the documented reason field.','Separate request acceptance from the later financial workflow.'],'The decisions are local fixture outputs; request_accepted is not refund completion or evidence of a remote effect.',
 ['A body owner or approval flag cannot replace server authority.','An authorized actor still needs valid input and current-state permission.','Enqueuing a financial request is not proof that money was reversed.'],['Review identity, target, fields and transition together.','Test cross-owner and overposting cases.','Keep financial workflow correctness and security boundaries coordinated.'],['authorization','input','rest']);
add('sec-input-output','m3.c1','Keep input data separate from SQL and output code',
 'A customer named O’Reilly should be searchable without changing a query’s structure. A support message containing formatting symbols should display as text in a plain-text area. Injection prevention depends on the destination context, not a universal remove-special-characters rule.',[
 section('Validate the input contract and parameterize values','Server-side validation enforces allowed fields, types, lengths and semantic rules even when a browser form was bypassed. It complements query construction but does not replace parameter binding. A driver placeholder sends a value separately from SQL syntax; identifier choices such as sort columns require an allowlisted mapping, not a value placeholder masquerading as a column name.','Avoid concatenating request input into query text or copying arbitrary body fields into internal models. Use least-privilege database credentials and constrained operations. A valid syntactic value can still refer to another user’s private object, so authorization remains required independently of the input schema.'),
 section('Output handling must match its interpretation context','An HTML text context can encode markup delimiters so submitted text is not interpreted as HTML. A JavaScript string, URL or HTML attribute has different rules. If rich HTML is truly allowed, use an appropriate maintained sanitizer under its policy; a plain escape helper is not a universal rich-content solution.','JSON serialization is not a universal XSS defense when a value is later placed into an unsafe browser sink. Prefer safe DOM APIs/text rendering and avoid string-built scripts or arbitrary HTML insertion. Content Security Policy can add a layer but is not a substitute for appropriate output handling and prevention at sinks.'),
 section('Verify a benign input and declared output context','The example uses a fixed name containing a quote and a standard parameterized SQLite query. It then encodes a harmless markup-shaped string for an explicitly HTML-text context. There is no exploitation payload, live endpoint or security-setting bypass.','These checks establish the shown query/output behavior only. They do not prove every query, template, nested serialization path or browser sink in an application is safe. Maintain negative contract/ownership cases and context-specific rendering tests as the product evolves.')],
 'import sqlite3, html\ndb = sqlite3.connect(":memory:")\ndb.execute("CREATE TABLE customers(name TEXT NOT NULL)")\ndb.execute("INSERT INTO customers(name) VALUES (?)", ("O\'Reilly",))\nname = "O\'Reilly"\nprint(db.execute("SELECT COUNT(*) FROM customers WHERE name=?", (name,)).fetchone()[0])\nprint(html.escape("<em>Welcome</em>"))\ndb.close()','1\n&lt;em&gt;Welcome&lt;/em&gt;',
 'Query a quoted synthetic name as data and render a markup-shaped message in an HTML text context.',['Bind the name through the driver rather than constructing SQL with it.','Read the matching fixture count.','Apply the output helper only under its stated HTML-text assumption.'],'The name matches as a value and the message is encoded as text. This is not a universal query builder, sanitizer or browser-security certification.',
 ['Input validation alone is not parameterized query construction.','Data placeholders cannot substitute arbitrary SQL identifiers.','Escaping for one output context does not secure every different sink.'],['Separate data from executable structure at each boundary.','Use context-appropriate output handling.','Retain independent authorization and least-privilege controls.'],['input','sql','xss']);
add('sec-browser-boundaries','m3.c1','Compose TLS, CORS, CSRF and cookie defenses',
 'A browser can attach a session cookie while making a request the user did not intend. At the same time, a legitimate dashboard may need to read an API on another origin. These are different browser boundaries and require distinct policies.',[
 section('Keep transport, origin and site concepts separate','Verified HTTPS protects transport between its peers, not every endpoint log or object permission. An origin normally combines scheme, host and effective port; a site relationship used by SameSite cookies is not the same boundary. Sibling subdomains can be same-site while remaining different origins.','CORS controls whether browser scripts may access cross-origin responses. It does not authenticate arbitrary clients, authorize objects or prevent every request from being sent. Configure explicit allowed origins/credentials as needed; arbitrary reflection and wildcard assumptions are not a safe credential policy. A non-browser client is not constrained into trust by the browser’s CORS mechanism.'),
 section('Protect authenticated state changes deliberately','For relevant cookie-authenticated operations, use reviewed CSRF defenses such as session-bound tokens, origin/fetch metadata checks and appropriate SameSite policy. Treat missing or special-origin contexts under an explicit policy rather than silently allowing them. Webhooks and non-browser integrations need their own authenticated design, not accidental blanket browser exceptions.','HttpOnly limits script reading of a cookie but does not prevent the browser from attaching it. SameSite is useful but not a complete defense for every product/subdomain flow. Verify content types and methods according to the API contract; simple cross-site form submissions and unexpected accepted content types can require particular care. XSS can undermine browser-side assumptions, so it still needs independent prevention.'),
 section('Model separate decisions instead of one magic flag','The fixture checks an exact origin allowlist for browser response access and a matching session-bound CSRF value for a synthetic state change. It assumes the session was already authenticated; it does not treat the origin as identity or implement the complete browser protocol.','A real implementation must handle preflight, credential rules, trusted proxies, token generation/comparison, missing headers and the application’s supported flows. Keep certificate and hostname verification enabled. Nothing in this example requires or permits disabling TLS checks, broadening production origins or testing public services.',{table:{headers:['Mechanism','Does not replace'],rows:[['HTTPS verification','Endpoint permissions and safe logs'],['CORS','Server authentication/authorization'],['HttpOnly','Every CSRF defense'],['SameSite','All origin/subdomain policy'],['CSRF token','XSS prevention or object checks']]}})],
 'import hmac\nallowed_origins = {"https://portal.example.test"}\ndef browser_policy(origin, supplied, session_token):\n    cors = origin in allowed_origins\n    csrf = cors and bool(supplied) and hmac.compare_digest(supplied, session_token)\n    return cors, csrf\nprint(browser_policy("https://portal.example.test", "fixture-csrf", "fixture-csrf"))\nprint(browser_policy("https://other.example.test", "fixture-csrf", "fixture-csrf"))\nprint(browser_policy("https://portal.example.test", "wrong", "fixture-csrf"))','(True, True)\n(False, False)\n(True, False)',
 'Distinguish allowed browser-origin response access from an additional session-token check for a synthetic state change.',['Match origins exactly against the fixture policy.','Require the intended session-bound token for the mutation decision.','Test wrong origin and wrong token independently.'],'A permitted origin alone does not pass the mutation check. This fixture is not a complete CORS middleware, CSRF service or authentication flow.',
 ['CORS is not a server-side object authorization system.','Same-site does not always mean same-origin.','HttpOnly and HTTPS do not independently prevent every unwanted authenticated browser request.'],['Name the transport/browser/permission boundaries explicitly.','Compose defenses for the supported request flows.','Test allowed, denied and missing-context cases without weakening configuration.'],['csrf','sessions','rest']);
add('sec-abuse-limits','m3.c2','Protect authentication and shared resources with bounded policies',
 'An educational API must remain usable when request volumes increase, and a sign-in flow must not permit unlimited guesses. Availability and account protection need layered limits tied to trusted context, not only a counter in one web process.',[
 section('Limit both attempts and the cost of each request','Use rate/quota policies appropriate to account, tenant, network and operation risk. Solely trusting a body user_id or an unverified forwarding header can misattribute requests. Configure proxy trust explicitly. Authentication/reset/MFA endpoints may need specialized controls and monitoring beyond a generic API throughput limit.','Bound body bytes, array size, nesting, decompressed size, query expansion, execution time and concurrency where applicable. A small request can still cause expensive work. Admission controls, bounded queues and workload isolation protect shared capacity; returning a limit error only after unbounded work has finished is too late.'),
 section('Choose fair enforcement and recovery tradeoffs','A fixed window is simple but can permit bursts around boundaries; sliding windows or token buckets have different behavior. Distributed deployments need a coordinated shared enforcement design or another reviewed consistency policy. A replica-local dictionary is not a platform-wide brute-force protection guarantee.','A 429 response can supply documented retry guidance. Retries remain bounded and appropriate to the operation. Avoid unreviewed permanent account lockouts that let one caller deny service to another; progressive controls, risk signals and independent MFA can be part of a balanced policy. Do not report an arbitrary threshold as universally secure.'),
 section('Test the declared counter without pretending it is distributed','The example uses a fixed synthetic clock and server-resolved actor key. It permits two calls in one minute, refuses the third and opens a new fixture window later. This shows exactly which policy is implemented and its boundary behavior.','It does not identify real users, trust network headers, synchronize replicas or model every anti-automation risk. Production thresholds should be measured and reviewed, and security events should avoid leaking submitted credentials or unnecessary personal information.')],
 'counts = {}\ndef allow(actor_id, now):\n    key = (actor_id, now // 60)\n    used = counts.get(key, 0)\n    if used >= 2:\n        return False\n    counts[key] = used + 1\n    return True\nprint(allow(7, 1), allow(7, 2), allow(7, 3))\nprint(allow(7, 61))\nprint(allow(8, 3))','True True False\nTrue\nTrue',
 'Apply a small fixed-window policy to synthetic trusted identities and a fixed clock.',['Construct the counter key from resolved identity and window.','Refuse a call after the stated fixture allowance.','Check a later window and a different identity separately.'],'The dictionary enforces this sequential local example. Its two-per-minute value is illustrative, not an operational security recommendation or multi-replica control.',
 ['A local counter does not establish global enforcement.','Request counts alone do not bound every request’s resource cost.','A permanent lockout can itself create availability harm if poorly designed.'],['Protect account flows and shared capacity together.','Choose trusted keys, coordinated enforcement and measured thresholds.','Test boundaries and keep retry/error behavior safe.'],['authentication','rest','input']);
add('sec-config-logs','m3.c3','Review secrets, configuration, dependencies and security evidence',
 'A backend moves from a local test to a production environment. Debug traces, overly broad credentials and permissive settings can expose data even when the endpoint code has reasonable checks. A secure release review must connect configuration to actual operational behavior.',[
 section('Manage secrets and defaults as explicit trust decisions','Keep provider credentials and signing secrets in appropriately protected server configuration/secret management, with minimum scope and controlled access. Do not bundle shared secrets in clients, commit them to Git or echo environment dumps into support logs. A leaked credential requires revocation/rotation and investigation, not merely removal from the latest file.','Environment variables are a delivery mechanism, not automatic proof that secrets are encrypted or inaccessible. Plan rotation, bounded overlap, usage verification and retirement. Keep TLS certificate/hostname checks enabled, disable unnecessary debug exposure and trust forwarding assertions only from configured ingress. Missing critical security configuration should fail closed under the deployment’s documented policy.'),
 section('Maintain dependencies and permission boundaries through change','Inventory direct/transitive dependencies, use controlled sources and lockfiles, review advisories and validate upgrades in isolated tests. Pinning alone does not prove vulnerability freedom; a scanner’s clean output does not prove complete security. Avoid removing authentication or loosening origins just to make a test green.','A development-to-production review should verify identity/permission tests, session/token lifecycle, input/output handling, resource limits and dependency/secret configuration. Separate environments and least-privilege service credentials reduce the impact of a mistake. A health check should not publish environment values, private stack traces or keys.'),
 section('Use structured evidence while minimizing disclosure','Record nonsecret correlation id, safe event category, verified actor reference where justified and the operation outcome needed for audit. Exclude passwords, raw session/access/refresh values and sensitive domain payloads. Use structured serialization to avoid treating an embedded newline as an additional trusted log event; control log access, integrity and retention under the actual organizational policy.','The fixture allowlists a minimal failed-authentication event and checks a synthetic configuration without printing secret values. It is not a recursive redaction framework, dependency scanner, secret store or production compliance test. Review nested/new fields and actual configured behavior before treating a policy declaration as enforcement.')],
 'import json\nconfig = {"verify_tls": True, "debug": False, "secret_present": True}\nassert config["verify_tls"] and not config["debug"] and config["secret_present"]\nevent = {"request_id": "req-demo", "category": "authentication_failed", "actor": "synthetic-account", "password": "SYNTHETIC-ONLY", "authorization": "SYNTHETIC-ONLY"}\nallowed = ("request_id", "category")\npublic_log = {k: event[k] for k in allowed}\nassert "password" not in public_log and "authorization" not in public_log\nprint(json.dumps(public_log, sort_keys=True))\nprint("configuration_policy_passed")','{"category": "authentication_failed", "request_id": "req-demo"}\nconfiguration_policy_passed',
 'Check explicit defensive settings and emit only allowlisted synthetic audit fields.',['Inspect policy booleans without dumping credential values.','Select known nonsecret event fields.','Verify sensitive fields are absent before serialization.'],'The output proves the fixture projection and declared settings only. It does not inspect real environment secrets, perform dependency scanning or establish all runtime controls.',
 ['Deleting a leaked key from one file does not revoke it.','A lockfile, scanner or environment variable is not a complete assurance claim.','Logging full requests can leak the credentials the authentication flow protects.'],['Review configuration and dependency lifecycle with code.','Use scoped, rotatable credentials and fail-closed critical settings.','Collect useful structured security evidence with controlled disclosure.'],['secrets','logging','rest']);
lessons.at(-1).sections.push(section('Synthesize a release review for a student portal',
 'The specification is a university portal with students reading their own results, teachers changing marks only for assigned classes, and finance staff reading fee summaries without academic notes. Document the verified actor, tenant/class membership, action grant, object ownership and allowed fields for every read, export and write. Test anonymous, expired, revoked, cross-student and cross-tenant requests, plus overposted managed fields and current-state conflicts. A signed credential is only the identity input to these decisions.',
 'Review the complete path: password/recovery/MFA assurance; session and refresh lifecycle; input schemas, parameter binding and safe output contexts; generic errors with private correlated diagnostics; request/body/time limits and coordinated retry behavior; TLS, browser origin/CSRF controls and trusted ingress; scoped secrets, dependency updates and rotation; audit access/retention and operational failure handling. Record expected outcomes and limitations before release. Local unit predicates do not establish cross-replica revocation, concurrent recovery consumption, provider atomicity or deployed configuration correctness.',
 {table:{headers:['Review evidence','Expected negative case'],rows:[['Identity and lifecycle','Expired/revoked credential rejected'],['Actor, object and fields','Another student’s record and managed fields denied'],['Limits and diagnostics','Bounded work; credentials absent from logs'],['Operational configuration','Untrusted origin/forwarding and missing critical settings fail safely']]}}));
const refs={passwords:'Password_Storage',authentication:'Authentication',sessions:'Session_Management',recovery:'Forgot_Password',mfa:'Multifactor_Authentication',authorization:'Authorization',input:'Input_Validation',sql:'SQL_Injection_Prevention',xss:'Cross_Site_Scripting_Prevention',csrf:'Cross-Site_Request_Forgery_Prevention',rest:'REST_Security',secrets:'Secrets_Management',logging:'Logging'};
module.exports={id:SID,version:1,state:'draft',language:'en',author:'EchoLens AI-assisted instructional draft',human_review:null,pass_mark:70,checkpoint_items:9,quiz_minutes:12,checkpoint_minutes:20,
 modules:C.subtrack(SID).modules.map(m=>({id:m.id,title:m.title,lessons:lessons.filter(l=>l.module===m.id).map(l=>l.id)})),lessons,questions:Object.values(questions).flat(),
 references:Object.entries(refs).map(([id,name])=>{const path='cheatsheets/'+name+'_Cheat_Sheet.md';return {id,title:'OWASP '+name.replaceAll('_',' ')+' Cheat Sheet',url:'https://github.com/OWASP/CheatSheetSeries/blob/'+COMMIT+'/'+path,source:{repo:'OWASP/CheatSheetSeries',commit:COMMIT,path,verification:'Pinned official OWASP guidance, original explanatory text. Offline fixture checks are not production security or compliance certification.'}};})};
